arguments.query:
dimension activities.pace_bucket_num = case(when: activities.avg_speed_ms is null, then: -1,when: activities.avg_speed_ms > 4.16667, then: 1,when: activities.avg_speed_ms > 3.33333, then: 2,when: activities.avg_speed_ms > 2.77778, then: 3,when: activities.avg_speed_ms > 2.381, then: 4,else: 5);
dimension activities.pace_bucket = case(when: activities.avg_speed_ms is null, then: 'unknown',when: activities.avg_speed_ms > 4.16667, then: '<4:00',when: activities.avg_speed_ms > 3.33333, then: '4–5',when: activities.avg_speed_ms > 2.77778, then: '5–6',when: activities.avg_speed_ms > 2.381, then: '6–7',else: '7+');
explore {
  dimensions {
    week_start: activities.week_start,
    bucket: activities.pace_bucket,
    bucket_num: activities.pace_bucket_num
  }
  measures {
    hours: run_time_h
  }
  sorts {
    week_start asc,
    bucket_num asc
  }
}
